"""
Safe Code Execution Helper for Classroom Exercises
Executes generated Python code snippets in an isolated subprocess with strict timeout
and captures stdout, stderr, and execution duration.
"""

import sys
import subprocess
import time
import os
import tempfile

class CodeExecutor:
    """Safe runner for code snippets generated by the Pedagogical Agent."""

    def __init__(self, timeout_seconds: float = 4.0, max_output_chars: int = 4000):
        self.timeout_seconds = timeout_seconds
        self.max_output_chars = max_output_chars

    def execute_python(self, code_str: str) -> dict:
        """
        Executes code_str in a sandboxed subprocess.
        Returns:
            dict with {
                'success': bool,
                'stdout': str,
                'stderr': str,
                'execution_time_ms': float,
                'timed_out': bool
            }
        """
        if not code_str or not code_str.strip():
            return {
                "success": False,
                "stdout": "",
                "stderr": "Empty code provided.",
                "execution_time_ms": 0.0,
                "timed_out": False
            }

        # Write code to a secure temporary file
        temp_file = None
        start_time = time.time()
        try:
            with tempfile.NamedTemporaryFile("w", suffix=".py", delete=False, encoding="utf-8") as tf:
                temp_file = tf.name
                tf.write(code_str)

            env = os.environ.copy()
            env["PYTHONIOENCODING"] = "utf-8"

            cmd = [sys.executable, "-u", temp_file]
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                env=env,
                cwd=tempfile.gettempdir()
            )

            try:
                stdout, stderr = proc.communicate(timeout=self.timeout_seconds)
                exec_time_ms = round((time.time() - start_time) * 1000, 2)
                return {
                    "success": proc.returncode == 0,
                    "stdout": stdout[:self.max_output_chars] if stdout else "",
                    "stderr": stderr[:self.max_output_chars] if stderr else "",
                    "execution_time_ms": exec_time_ms,
                    "timed_out": False,
                    "returncode": proc.returncode
                }
            except subprocess.TimeoutExpired:
                proc.kill()
                stdout, stderr = proc.communicate()
                exec_time_ms = round((time.time() - start_time) * 1000, 2)
                return {
                    "success": False,
                    "stdout": stdout[:self.max_output_chars] if stdout else "",
                    "stderr": f"Execution timed out after {self.timeout_seconds} seconds.",
                    "execution_time_ms": exec_time_ms,
                    "timed_out": True,
                    "returncode": -1
                }

        except Exception as e:
            exec_time_ms = round((time.time() - start_time) * 1000, 2)
            return {
                "success": False,
                "stdout": "",
                "stderr": f"Execution error: {str(e)}",
                "execution_time_ms": exec_time_ms,
                "timed_out": False,
                "returncode": -1
            }
        finally:
            if temp_file and os.path.exists(temp_file):
                try:
                    os.remove(temp_file)
                except OSError:
                    pass
